import http from 'k6/http';
import { SharedArray } from 'k6/data';

export const BASE_URL = __ENV.BASE_URL || 'http://localhost:3000';
export const RATE = Number(__ENV.RATE || 2000);
export const DURATION = __ENV.DURATION || '30s';
export const LABEL = __ENV.LABEL || 'local';

// codes.json is generated by loadtest/seed.ts and gitignored; smoke.js does not use it.
export const codes = new SharedArray('codes', function () {
  try {
    return JSON.parse(open('./codes.json'));
  } catch {
    return [];
  }
});

const JSON_HEADERS = { 'content-type': 'application/json' };
const OK_REDIRECT = http.expectedStatuses(302, 404);

// 80% of requests go to the first 20% of codes (hot set), the rest anywhere.
export function pickCode() {
  const hot = Math.max(1, Math.floor(codes.length * 0.2));
  if (Math.random() < 0.8) {
    return codes[Math.floor(Math.random() * hot)];
  }
  return codes[Math.floor(Math.random() * codes.length)];
}

function randomUnknown() {
  return 'nx' + Math.random().toString(36).slice(2, 12);
}

// ~2% of redirects hit a code that does not exist (404).
export function redirect(unknownShare = 0.02) {
  let code = pickCode();
  let expected = 302;
  if (Math.random() < unknownShare) {
    code = randomUnknown();
    expected = 404;
  }
  return {
    res: http.get(`${BASE_URL}/${code}`, {
      redirects: 0,
      tags: { name: 'redirect' },
      responseCallback: OK_REDIRECT,
    }),
    expected,
  };
}

export function createLink(url, statuses) {
  return http.post(`${BASE_URL}/api/links`, JSON.stringify({ url }), {
    headers: JSON_HEADERS,
    redirects: 0,
    tags: { name: 'create' },
    responseCallback: http.expectedStatuses(...statuses),
  });
}

function fmt(v) {
  return typeof v === 'number' ? v.toFixed(2) : String(v);
}

// Compact stdout summary plus the full data as JSON in loadtest/results/.
export function summarize(name, data) {
  const lines = [`== ${name} (${LABEL}) ==`];
  const m = data.metrics;
  const count = (k) => (m[k] ? m[k].values.count : 0);
  lines.push(
    `requests=${count('http_reqs')} dropped=${count('dropped_iterations')}` +
      ` failed=${fmt((m.http_req_failed ? m.http_req_failed.values.rate : 0) * 100)}%` +
      ` checks=${fmt((m.checks ? m.checks.values.rate : 1) * 100)}%`,
  );
  for (const key of Object.keys(m)) {
    if (key.indexOf('http_req_duration') !== 0) continue;
    const v = m[key].values;
    lines.push(
      `${key}: p50=${fmt(v.med)} p95=${fmt(v['p(95)'])} p99=${fmt(v['p(99)'])} max=${fmt(v.max)} ms`,
    );
  }
  for (const key of Object.keys(m)) {
    const t = m[key].thresholds;
    if (!t) continue;
    for (const expr of Object.keys(t)) {
      lines.push(`${t[expr].ok ? 'PASS' : 'FAIL'} ${key} ${expr}`);
    }
  }
  const out = {
    stdout: lines.join('\n') + '\n',
  };
  out[`loadtest/results/${name}-${LABEL}.json`] = JSON.stringify(data);
  return out;
}

export const TREND_STATS = ['med', 'p(95)', 'p(99)', 'max', 'avg'];
